require_once __DIR__.'/shared-components/auth.php';require_once __DIR__.'/database-config/connection.php';require_once __DIR__.'/shared-components/functions.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();requireRole('organiser');$user_id=(int)($_SESSION['UserID']??0);if(!$user_id){header('Location: login.php');exit;}
